`timescale 1ns / 1ps

// ham_a: signed 8 x 8 hybrid approximate multiplier HAM-A (H7C0) of Shi et al.
// (IEEE TVLSI 33(10) 2025, Fig. 3, eq. 6): leading-one exponent and 5-bit mantissa,
// mixed piecewise-linear fit of the mantissa product in five zones (X2 3 bits, X4
// 5 bits, biases 33/25/24/32/5 / 32), shift by the exponent sum,
// sign compensation of the result (exact negation of p1_PWL), partial-complement (PACC) operand magnitudes.
// A zero magnitude gives 0. Reference model: approx/ham.py.
// a = weight, b = activation, p = a * b (signed, 16 bit).
// Generated by python3 -m src_gan_tsmc65.approx.gen (do not edit).

// exponent / mantissa conversion: x (> 0) -> k = leading-one position, f = the 5
// bits after the leading one
module ham_a_emc (
    input  wire [6:0] x,
    output reg  [2:0] k,
    output wire [4:0] f
);
    integer i;
    always @* begin
        k = 0;
        for (i = 1; i < 7; i = i + 1)
            if (x[i]) k = i;
    end
    wire [6:0] xs = x << (6 - k);       // leading one to bit 6
    assign f = xs[5:1];
endmodule

// mixed PWL fit of (1 + f1)(1 + f2) in units of 2^-5, sign compensated: the result is
// p1 for neg = 0 and p1 - 1 for neg = 1
module ham_a_pwl (
    input  wire [4:0] f1,
    input  wire [4:0] f2,
    input  wire       neg,
    output wire [6:0] s
);
    wire [5:0] x1 = f1 + f2;
    wire signed [3:0] x2 = $signed({1'b0, f1[4:2]}) - $signed({1'b0, f2[4:2]});
    wire [2:0] ax2 = x2[3] ? -x2[2:0] : x2[2:0];
    wire [3:0] x3 = f1[4:2] + f2[4:2];
    wire [4:0] x4 = (x2[3] ? f1 : f2) & 5'b11111;   // min(f1, f2), 5 MSBs
    wire zn1 = x3 < 4;
    wire zn5 = x3 >= 10;
    wire zn2 = ~zn1 & ~zn5 & (ax2 <= 1);
    wire zn4 = ~zn1 & ~zn5 & (ax2 >= 5);
    wire [6:0] t1 = zn5 ? {x1, 1'b0} : {1'b0, x1};
    wire [6:0] t2 = zn1 ? x4 >> 2 : zn4 ? x4 : zn5 ? -(x1 >> 4) : x1 >> 1;
    wire [6:0] bias = zn1 ? 7'd32 : zn5 ? 7'd4 : zn2 ? 7'd24 :
                        zn4 ? 7'd31 : 7'd23;
    assign s = t1 + t2 + bias + {6'd0, ~neg};   // vacant carry bit = ~sign
endmodule

module gan_mul8 (
    input  wire signed [7:0]  a,
    input  wire signed [7:0]  b,
    output wire signed [15:0] p
);
    // ME, partial complement: ~a[6:4] and ~a[3:0] + 1 without carry out
    wire [6:0] ia = ~a[6:0];
    wire [3:0] la = ia[3:0] + 4'd1;
    wire [6:0] ma = a[7] ? {ia[6:4], la} : a[6:0];
    // ME, partial complement: ~b[6:4] and ~b[3:0] + 1 without carry out
    wire [6:0] ib = ~b[6:0];
    wire [3:0] lb = ib[3:0] + 4'd1;
    wire [6:0] mb = b[7] ? {ib[6:4], lb} : b[6:0];
    wire [2:0] ka, kb;
    wire [4:0] fa, fb;
    ham_a_emc u_ea (.x(ma), .k(ka), .f(fa));
    ham_a_emc u_eb (.x(mb), .k(kb), .f(fb));
    wire neg = a[7] ^ b[7];
    wire [6:0] s;
    ham_a_pwl u_pwl (.f1(fa), .f2(fb), .neg(neg), .s(s));
    // MTS: one's complement of the compensated result (= -p1 for a negative product)
    wire signed [7:0] o = {neg, s ^ {7{neg}}};
    // SHIFT: o * 2^(ka + kb - 5), arithmetic right shifts truncate
    wire [3:0] k = {1'b0, ka} + kb;              // K - 2
    wire signed [23:0] sh = $signed(o) <<< k;
    wire signed [23:0] r = sh >>> 5;
    assign p = (~|ma | ~|mb) ? 16'sd0 : r[15:0];
endmodule
